// Initialize state with comprehensive error handling
const input = $input.first().json;

// Validate required fields
if (!input.chatInput || typeof input.chatInput !== 'string') {
  throw new Error('Invalid input: chatInput is required and must be a string');
}

const state = {
  sessionId: input.sessionId || $execution.id,
  userQuery: input.chatInput.trim(),
  history: Array.isArray(input.history) ? input.history : [],
  phase: 'planning',
  plan: null,
  currentStep: 0,
  stepResults: [],
  iterations: 0,
  maxIterations: parseInt($env.MAX_ITERATIONS) || 5,
  maxStepsPerPlan: parseInt($env.MAX_STEPS_PER_PLAN) || 10,
  events: [],
  errors: [],
  startTime: Date.now(),
  executionId: $execution.id,
  metadata: {
    inputLength: input.chatInput.length,
    historyLength: (input.history || []).length,
    timestamp: new Date().toISOString()
  }
};

// Emit RUN_STARTED event
state.events.push({
  type: 'RUN_STARTED',
  runId: $execution.id,
  threadId: state.sessionId,
  timestamp: new Date().toISOString()
});

return { json: state };

// Parse and validate planning agent output with comprehensive error handling
const state = $('Initialize State').first().json;
const agentOutput = $input.first().json;

try {
  let plan;

  // Handle both structured output and raw text
  if (agentOutput.output && typeof agentOutput.output === 'object') {
    plan = agentOutput.output;
  } else if (agentOutput.output && typeof agentOutput.output === 'string') {
    const jsonMatch = agentOutput.output.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('No valid JSON found in planner output');
    plan = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Invalid planner output format');
  }

  // Validate plan structure
  if (!plan.goal || !Array.isArray(plan.steps) || plan.steps.length === 0) {
    throw new Error('Invalid plan: missing goal or steps');
  }

  // Enforce step limits
  if (plan.steps.length > state.maxStepsPerPlan) {
    plan.steps = plan.steps.slice(0, state.maxStepsPerPlan);
    plan.truncated = true;
  }

  // Add default values to steps
  plan.steps = plan.steps.map((step, idx) => ({
    id: step.id || `step_${idx + 1}`,
    description: step.description || 'Unnamed step',
    tool: step.tool || 'none',
    toolInput: step.toolInput || '',
    expectedOutput: step.expectedOutput || 'Output not specified',
    dependsOn: step.dependsOn || [],
    timeout: step.timeout || 60000,
    retryCount: step.retryCount || 1,
    status: 'pending'
  }));

  state.plan = plan;
  state.phase = 'executing';

  // Emit events
  state.events.push(
    {
      type: 'STEP_STARTED',
      stepId: 'planning',
      stepName: 'Creating execution plan',
      stepType: 'planning',
      timestamp: new Date().toISOString()
    },
    {
      type: 'STATE_DELTA',
      delta: [
        { op: 'replace', path: '/phase', value: 'executing' },
        { op: 'add', path: '/plan', value: plan }
      ],
      timestamp: new Date().toISOString()
    },
    {
      type: 'STEP_FINISHED',
      stepId: 'planning',
      status: 'complete',
      result: { stepsCount: plan.steps.length, complexity: plan.complexity },
      timestamp: new Date().toISOString()
    }
  );

} catch (error) {
  state.errors.push({
    phase: 'planning',
    message: error.message,
    timestamp: new Date().toISOString()
  });
  state.phase = 'error';
  state.errorMessage = `Planning failed: ${error.message}`;
}

return { json: state };

