// Process manager agent result with comprehensive error handling
const prevState = $('More Steps?').first().json;
const managerOutput = $input.first().json;

const state = JSON.parse(JSON.stringify(prevState));

try {
  const currentStep = state.plan.steps[state.currentStep];
  const hasError = managerOutput.error || !managerOutput.output;

  // Record step result
  const stepResult = {
    stepId: currentStep.id,
    description: currentStep.description,
    tool: currentStep.tool,
    result: hasError ? { error: managerOutput.error || 'No output' } : managerOutput.output,
    success: !hasError,
    toolCalls: managerOutput.intermediateSteps || [],
    startedAt: currentStep.startedAt || new Date().toISOString(),
    completedAt: new Date().toISOString(),
    duration: Date.now() - (currentStep.startedAtMs || Date.now())
  };

  state.stepResults.push(stepResult);

  // Emit TOOL_CALL events
  if (managerOutput.intermediateSteps) {
    for (const step of managerOutput.intermediateSteps) {
      if (step.action && step.action.tool) {
        state.events.push({
          type: 'TOOL_CALL_START',
          toolCallId: step.action.toolCallId || `tool_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          toolCallName: step.action.tool,
          timestamp: new Date().toISOString()
        });

        state.events.push({
          type: 'TOOL_CALL_RESULT',
          toolCallId: step.action.toolCallId || `tool_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
          result: typeof step.observation === 'string' ? step.observation.slice(0, 1000) : JSON.stringify(step.observation).slice(0, 1000),
          timestamp: new Date().toISOString()
        });
      }
    }
  }

  // Update step status
  state.plan.steps[state.currentStep].status = hasError ? 'failed' : 'complete';

  // Emit STEP_FINISHED
  state.events.push({
    type: 'STEP_FINISHED',
    stepId: currentStep.id,
    status: hasError ? 'failed' : 'complete',
    result: { summary: stepResult.result?.toString?.()?.slice(0, 200) || 'Completed' },
    timestamp: new Date().toISOString()
  });

  // Move to next step
  state.currentStep++;
  state.iterations++;

  // Emit STATE_DELTA
  state.events.push({
    type: 'STATE_DELTA',
    delta: [
      { op: 'replace', path: '/plan/currentStepIndex', value: state.currentStep },
      { op: 'add', path: '/stepResults/-', value: stepResult }
    ],
    timestamp: new Date().toISOString()
  });

  // Emit next STEP_STARTED if more steps
  if (state.currentStep < state.plan.steps.length) {
    const nextStep = state.plan.steps[state.currentStep];
    nextStep.startedAt = new Date().toISOString();
    nextStep.startedAtMs = Date.now();
    nextStep.status = 'active';

    state.events.push({
      type: 'STEP_STARTED',
      stepId: nextStep.id,
      stepName: nextStep.description,
      stepType: nextStep.tool,
      timestamp: new Date().toISOString()
    });
  }

} catch (error) {
  state.errors.push({
    phase: 'execution',
    step: state.currentStep,
    message: error.message,
    timestamp: new Date().toISOString()
  });
}

return { json: state };

