// Parse QC result with error handling
const state = $('More Steps?').first().json;
const qcOutput = $input.first().json;

try {
  let qcResult;

  // Handle structured or raw output
  if (qcOutput.output && typeof qcOutput.output === 'object') {
    qcResult = qcOutput.output;
  } else if (qcOutput.output && typeof qcOutput.output === 'string') {
    const jsonMatch = qcOutput.output.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('No JSON in QC output');
    qcResult = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Invalid QC output format');
  }

  // Ensure required fields
  qcResult = {
    approved: qcResult.approved ?? true,
    qualityScore: Math.min(10, Math.max(1, qcResult.qualityScore || 5)),
    issues: qcResult.issues || [],
    suggestions: qcResult.suggestions || [],
    requiresRevision: qcResult.requiresRevision ?? false,
    revisionInstructions: qcResult.revisionInstructions || '',
    finalSummary: qcResult.finalSummary || 'Task completed.',
    reasoning: qcResult.reasoning || ''
  };

  state.qcResult = qcResult;
  state.phase = qcResult.approved ? 'complete' : 'revision_needed';

  // Emit QC events
  state.events.push(
    {
      type: 'STEP_STARTED',
      stepId: 'quality_control',
      stepName: 'Quality Control Review',
      stepType: 'review',
      timestamp: new Date().toISOString()
    },
    {
      type: 'STEP_FINISHED',
      stepId: 'quality_control',
      status: qcResult.approved ? 'complete' : 'failed',
      result: { qualityScore: qcResult.qualityScore, approved: qcResult.approved },
      timestamp: new Date().toISOString()
    },
    {
      type: 'STATE_DELTA',
      delta: [
        { op: 'replace', path: '/phase', value: state.phase },
        { op: 'add', path: '/qualityScore', value: qcResult.qualityScore }
      ],
      timestamp: new Date().toISOString()
    }
  );

} catch (error) {
  // Default to approved on QC parse error to avoid blocking
  state.qcResult = {
    approved: true,
    qualityScore: 5,
    issues: [`QC parsing error: ${error.message}`],
    suggestions: [],
    requiresRevision: false,
    revisionInstructions: '',
    finalSummary: state.stepResults.map(r => r.result).join('\n\n') || 'Task completed with QC warnings.',
    reasoning: 'QC parsing failed, defaulting to approved'
  };
  state.phase = 'complete';
  state.errors.push({
    phase: 'qc',
    message: error.message,
    timestamp: new Date().toISOString()
  });
}

return { json: state };

// Generate final response
const state = $json;

// Emit RUN_FINISHED
state.events.push({
  type: 'RUN_FINISHED',
  runId: state.executionId,
  threadId: state.sessionId,
  status: state.phase === 'complete' ? 'success' : (state.phase === 'error' ? 'error' : 'partial'),
  timestamp: new Date().toISOString()
});

// Build final output
const finalResponse = {
  success: state.phase === 'complete' || state.phase === 'revision_needed',
  output: state.qcResult?.finalSummary || state.errorMessage || 'Task processing completed.',
  plan: state.plan,
  stepResults: state.stepResults,
  qualityScore: state.qcResult?.qualityScore || null,
  iterations: state.iterations,
  events: state.events,
  errors: state.errors,
  metadata: {
    executionId: state.executionId,
    sessionId: state.sessionId,
    executionTime: Date.now() - state.startTime,
    totalSteps: state.plan?.steps?.length || 0,
    completedSteps: state.stepResults.length,
    phase: state.phase
  }
};

return { json: finalResponse };

// Prepare for revision loop
const state = JSON.parse(JSON.stringify($json));

state.currentStep = 0;
state.stepResults = [];
state.phase = 'executing';
state.iterations++;

// Clear step statuses
state.plan.steps.forEach(step => {
  step.status = 'pending';
  delete step.startedAt;
  delete step.startedAtMs;
});

// Emit revision events
state.events.push(
  {
    type: 'STEP_STARTED',
    stepId: 'revision',
    stepName: `Revision ${state.iterations}: ${state.qcResult?.revisionInstructions?.slice(0, 100) || 'Re-executing plan'}`,
    stepType: 'revision',
    timestamp: new Date().toISOString()
  },
  {
    type: 'STATE_DELTA',
    delta: [
      { op: 'replace', path: '/phase', value: 'executing' },
      { op: 'replace', path: '/iterations', value: state.iterations }
    ],
    timestamp: new Date().toISOString()
  }
);

return { json: state };

// Handle planning error - generate error response
const state = $json;

state.events.push({
  type: 'RUN_FINISHED',
  runId: state.executionId,
  threadId: state.sessionId,
  status: 'error',
  timestamp: new Date().toISOString()
});

const errorResponse = {
  success: false,
  error: state.errorMessage || 'Planning failed',
  output: `I encountered an error while planning: ${state.errorMessage}. Please try rephrasing your request.`,
  events: state.events,
  errors: state.errors,
  metadata: {
    executionId: state.executionId,
    sessionId: state.sessionId,
    executionTime: Date.now() - state.startTime,
    phase: 'error'
  }
};

return { json: errorResponse };
